	tn := newTestNet(t, 4, 1, nil)
	tn.cfg.MaxEvidence = 4
	c := mustNew(t, tn.cfg)

	// Many conflicting tuples for one (replica, height): one proof only.
	h := uint64(1)
	for k := 0; k < 1000; k++ {
		c.AddVote(tn.sign(0, tn.ckpt(h, byte(k), uint64(k)), 0))
	}
	if got := len(c.Equivocations()); got != 1 {
		t.Fatalf("same (replica,height) flood produced %d proofs, want 1", got)
	}

	// Many heights: total evidence never exceeds MaxEvidence.
	for hh := uint64(2); hh < 1000; hh++ {
		c.AddVote(tn.sign(0, tn.ckpt(hh, 0x01, 1), 0))
		c.AddVote(tn.sign(0, tn.ckpt(hh, 0x02, 1), 1))
		if got := len(c.Equivocations()); got > tn.cfg.MaxEvidence {
			t.Fatalf("evidence buffer grew to %d > cap %d", got, tn.cfg.MaxEvidence)
		}
	}
}

// TestOversizedCertificateRejected checks the input cap that prevents an
// allocation attack through Commit/VerifyCertificate.
func TestOversizedCertificateRejected(t *testing.T) {
	tn := newTestNet(t, 4, 1, nil)
	ck := tn.ckpt(1, 0x01, 1)
	cert := Certificate{Checkpoint: ck}
	for i := 0; i < tn.cfg.N+1; i++ { // N+1 > N
		cert.Votes = append(cert.Votes, tn.sign(i%tn.cfg.N, ck, 0))
	}
	if err := VerifyCertificate(tn.cfg, cert); !errors.Is(err, ErrBadCertificate) {
		t.Fatalf("oversized certificate not rejected: %v", err)
	}
}

// TestSignersAndSorting checks deterministic certificate signer ordering.
func TestSignersAndSorting(t *testing.T) {
	tn := newTestNet(t, 4, 1, nil)
	ck := tn.ckpt(1, 1, 1)
	cert := Certificate{Checkpoint: ck, Votes: []Vote{
		tn.sign(3, ck, 0), tn.sign(1, ck, 0), tn.sign(2, ck, 0), tn.sign(1, ck, 0),
	}}
	got := cert.Signers()
	want := []ReplicaID{1, 2, 3}
	if len(got) != len(want) {
		t.Fatalf("signers=%v want %v", got, want)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("signers=%v want %v", got, want)
		}
	}
	if !sort.SliceIsSorted(got, func(i, j int) bool { return got[i] < got[j] }) {
		t.Fatal("signers not sorted")
	}
}
